};

const limparBase = v => v === null || v === undefined ? '' : String(v).replace(/["']/g, '').trim();
const formatarCPF = v => '="' + String(v ?? '').replace(/\D/g, '').padStart(11, '0').slice(-11) + '"';
const formatarTelefone = v => limparBase(v).replace(/\D/g, '');
const formatarEmail = v => limparBase(v).toLowerCase();

const calcularDataPorDias = dias => {
  const diasNum = parseInt(dias, 10);
  if (isNaN(diasNum)) return '';
  const hoje = new Date();
  hoje.setDate(hoje.getDate() - diasNum);
  return hoje.getFullYear() +
    String(hoje.getMonth() + 1).padStart(2, '0') +
    String(hoje.getDate()).padStart(2, '0');
};

const formatarValor = v => {
  if (v === null || v === undefined || v === '') return '="0,00"';
  const s = String(v).trim().replace(/[^\d.,]/g, '');
  let num;
  if (/^\d{1,3}(\.\d{3})*,\d+$/.test(s)) {
    num = parseFloat(s.replace(/\./g, '').replace(',', '.'));
  } else if (/^\d+\.\d+$/.test(s)) {
    num = parseFloat(s);
  } else {
    num = parseFloat(s.replace(',', '.'));
  }
  if (isNaN(num)) return '="0,00"';
  return '="' + num.toFixed(2).replace('.', ',') + '"';
};

let inputData = $input.all().map(i => i.json);
if (inputData.length === 1 && Array.isArray(inputData[0].data)) inputData = inputData[0].data;

inputData = inputData.filter(row => {
  const chaveStatus = Object.keys(row).find(k => normalizarStatus(k) === 'status');
  if (!chaveStatus) return false;
  return normalizarStatus(row[chaveStatus]) === 'inadimplente';
});

const output = inputData.map(row => {
  const novo = {};
  for (const [saida, entrada] of Object.entries(map)) {
    let valor = entrada ? row[entrada] ?? '' : '';
    switch (saida) {
      case 'CPF (A)': case 'CPF (D)': case 'CPF (S)':
        valor = formatarCPF(valor); break;
      case 'TELEFONE (K)': case 'TELEFONE (Z)':
        valor = formatarTelefone(valor); break;
      case 'EMAIL (Q)': case 'EMAIL (AB)':
        valor = formatarEmail(valor); break;
      case 'DATA RECEBIVEL RECENTE (O)':
        valor = calcularDataPorDias(row['DIAS_INADIMPLENTE']); break;
