        valor = formatarValor(valor); break;
      case 'MENSALIDADE (N)':
        valor = 'MENSALIDADE'; break;
      default:
        valor = limparBase(valor);
    }
    novo[saida] = String(valor);
  }
  return { json: novo };
});

return output.filter(item => Object.values(item.json).some(v => v !== ''));

