// 🔧 Funções auxiliares seguras
const limparTexto = t => {
  if (t === null || t === undefined) return '';
  const str = String(t);
  if (typeof str.normalize !== 'function') return str.trim();
  return str
    .normalize('NFD')                     // remove acentuação
    .replace(/[\u0300-\u036f]/g, '')      // remove diacríticos
    .replace(/[.,;:()\-]/g, '')           // remove pontuação
    .trim();
};

const formatarCPF = v => !v
  ? '00000000000'
  : v.toString().replace(/\D/g, '').padStart(11, '0').slice(-11);

const formatarData = d => {
  if (!d) return '';
  const obj = new Date(d);
  if (!isNaN(obj))
    return `${obj.getFullYear()}${String(obj.getMonth() + 1).padStart(2, '0')}${String(obj.getDate()).padStart(2, '0')}`;
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(d)) {
    const [dia, mes, ano] = d.split('/');
    return `${ano}${mes.padStart(2, '0')}${dia.padStart(2, '0')}`;
  }
  return '';
};

const formatarValor = v =>
  !v
    ? '0,00'
    : (parseFloat(v.toString().replace(/[^\d,.-]/g, '').replace(',', '.')) || 0)
        .toFixed(2)
        .replace('.', ',');

const limparEmail = e =>
  e ? e.toString().replace(/['"]/g, '').trim() : '';

const formatarTelefone = v =>
  v ? limparTexto(v.toString()) : '';

// 🔍 Lê dados
