        valor = limparEmail(valor);
        break;
      case 'TELEFONE (K)':
      case 'TELEFONE (Z)':
        valor = formatarTelefone(valor);
        break;
      default:
        valor = limparTexto(valor);
    }
    novo[saida] = valor;
  }

  return { json: novo };
});

// Remove linhas totalmente vazias
return output.filter(item =>
  Object.values(item.json).some(v => v && v !== '')
);

const binaryData = await this.helpers.getBinaryDataBuffer(0, 'file0');
const raw = binaryData.toString('utf-8');

const lines = raw.split('\r\n');
const delimiter = lines[0].includes(';') ? ';' : ',';
const output = [];

for (const line of lines) {
  if (!line.trim()) continue;

  let l = line;

  if (l.startsWith('"') && l.endsWith('"')) {
    l = l.slice(1, -1);
  }

  l = l.replace(/""/g, '\x01');

  let parts = l.split(delimiter);
  parts = parts.slice(0, 13);

  const cleaned = parts.map(cell => {
    cell = cell.replace(/\x01/g, '').trim();
    cell = cell.replace(/^(\d+),(\d+)$/, '$1.$2');
    cell = cell.replace(/,/g, ' | ');
    cell = cell.replace(/"/g, '');
    return cell;
  });

  if (delimiter === ',' && cleaned.length === 13 &&
      /^\d+$/.test(cleaned[5]) && /^\d{1,2}$/.test(cleaned[6])) {
    cleaned[5] = cleaned[5] + '.' + cleaned[6];
    cleaned.splice(6, 1);
    cleaned.push('');
  }

  output.push(cleaned.join(','));
}

const newCsv = output.join('\r\n');
const newBinary = await this.helpers.prepareBinaryData(
  Buffer.from(newCsv, 'utf-8'),
  'cleaned.csv',
  'text/csv'
);

return [{ json: {}, binary: { file0: newBinary } }];
